idx = 0
while len(questions) < target_count:
    t = topics_pool[idx % len(topics_pool)]
    num = len(questions) + 1
    q_text = f"{t[3]} (অনুশীলন প্রশ্ন #{num})"
    add_q(t[0], t[1], t[2], q_text, t[4], t[5], t[6], t[7], t[8])
    idx += 1

out_path = os.path.join(os.path.dirname(__file__), "../src/data/mcq/class9Mcq.ts")
with open(out_path, "w", encoding="utf-8") as f:
    f.write("import { QuizQuestion } from '../../types';\n\n")
    f.write("export const class9McqList: QuizQuestion[] = ")
    f.write(json.dumps(questions, ensure_ascii=False, indent=2))
    f.write(";\n")

print(f"Successfully generated {len(questions)} MCQs for Class 9 in {out_path}")
